<?php
require __DIR__.'/../cms/config.php'; require_login(); $u=current_user();
$students=read_json('students');$parents=read_json('parents');$classes=read_json('classes');$subjects=read_json('subjects');$results=read_json('results');$attendance=read_json('attendance');$ledger=read_json('ledger');
$id=(int)($_GET['student_id']??0);
if($u['role']==='student') $id=(int)$u['profile_id'];
if($u['role']==='parent'){
 $allowed=array_map(fn($x)=>(int)$x['id'],array_filter($students,fn($x)=>(int)($x['parent_id']??0)===(int)$u['profile_id']));
 if(!in_array($id,$allowed,true)) $id=$allowed[0]??0;
}
if(in_array($u['role'],['admin','teacher'],true)){} elseif(!$id){http_response_code(403);exit('Access denied.');}
$st=null;foreach($students as $x)if((int)$x['id']===$id){$st=$x;break;}if(!$st){http_response_code(404);exit('Student record not found.');}
function nm($a,$id){foreach($a as $x)if((int)($x['id']??0)===(int)$id)return $x['name']??'';return '—';}
function pct2($m,$o){return $o?(float)round($m/$o*100,1):0;}
$rows=array_values(array_filter($results,fn($r)=>(int)$r['student_id']===$id));usort($rows,fn($a,$b)=>strcmp($a['created_at']??'',$b['created_at']??''));
$att=array_values(array_filter($attendance,fn($r)=>(int)$r['student_id']===$id));$present=count(array_filter($att,fn($a)=>in_array($a['status']??'', ['Present','Late'],true)));$rate=count($att)?round($present/count($att)*100,1):null;
$lr=array_values(array_filter($ledger,fn($r)=>(int)$r['student_id']===$id));$balance=0;foreach($lr as $l)$balance+=(in_array($l['type']??'',['Payment','Credit'],true)?-1:1)*(float)$l['amount'];
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h($st['name'])?> — Ridgefield</title><link rel="stylesheet" href="../cms/cms.css"><style>
.wrap{max-width:1200px;margin:auto;padding:28px}.top{display:flex;justify-content:space-between;gap:15px;align-items:center;margin-bottom:20px}.hero{background:#17312a;color:#fff;border-radius:20px;padding:30px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin:18px 0}.card{background:#fff;border:1px solid #dde3dd;border-radius:15px;padding:20px}.metric{font-size:32px;font-weight:700}.wide{grid-column:1/-1}.table{width:100%;border-collapse:collapse}.table th,.table td{padding:10px;border-bottom:1px solid #e2e6e2;text-align:left}.chart{height:300px;display:flex;align-items:flex-end;gap:10px;padding:10px;overflow-x:auto;border-bottom:1px solid #d9ded9}.barwrap{min-width:60px;height:260px;display:flex;flex-direction:column;justify-content:flex-end;align-items:center;gap:5px}.bar{width:34px;background:#b28b45;border-radius:6px 6px 0 0}.label{font-size:10px;max-width:70px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;transform:rotate(-35deg);margin-top:10px}.muted{color:#68746f}@media(max-width:800px){.grid{grid-template-columns:1fr}.wide{grid-column:auto}.wrap{padding:16px}.top{flex-direction:column;align-items:flex-start}}
