</head><body class="rf-dynamic"><div class="wrap"><div class="top"><strong>RIDGEFIELD ACADEMY</strong><span><a href="index.php">Portal</a> · <a href="report.php?student_id=<?=h((string)$id)?>">Report card</a> · <a href="change-password.php">Change password</a> · <a href="logout.php">Sign out</a></span></div>
<section class="hero"><p class="eyebrow">PRIVATE LEARNER PROFILE</p><h1><?=h($st['name'])?></h1><p><?=h($st['student_no']??'')?> · Grade <?=h($st['grade']??'')?> · <?=h(nm($classes,(int)($st['class_id']??0)))?></p></section>
<div class="grid"><div class="card"><div class="metric"><?=h($st['status']??'Active')?></div><p class="muted">Student status</p></div><div class="card"><div class="metric"><?=h($rate===null?'—':$rate.'%')?></div><p class="muted">Attendance rate</p></div><div class="card"><div class="metric">R <?=number_format($balance,2)?></div><p class="muted">Current account balance</p></div>
<div class="card"><div class="metric"><?=h(($ov=average_for_student($results,$id))===null?"—":$ov."%")?></div><p class="muted">Overall academic average</p></div><div class="card wide"><h2>Performance over time</h2><p class="muted">Assessment results are shown chronologically so progress can be monitored.</p><div class="chart"><?php if(!$rows):?><p class="muted">No results have been published yet.</p><?php else: foreach($rows as $r):$v=pct2($r['mark']??0,$r['out_of']??100);?><div class="barwrap" title="<?=h(nm($subjects,(int)$r['subject_id']).' — '.($r['assessment']??'').' — '.$v.'%')?>"><strong><?=h((string)$v)?>%</strong><div class="bar" style="height:<?=max(3,min(240,$v*2.4))?>px"></div><span class="label"><?=h(nm($subjects,(int)$r['subject_id']))?></span></div><?php endforeach;endif;?></div></div>
<div class="card wide"><h2>Academic results</h2><table class="table"><tr><th>Term</th><th>Subject</th><th>Assessment</th><th>Mark</th><th>Comment</th></tr><?php foreach(array_reverse($rows) as $r):?><tr><td><?=h($r['term']??'')?></td><td><?=h(nm($subjects,(int)$r['subject_id']))?></td><td><?=h($r['assessment']??'')?></td><td><strong><?=h((string)$r['mark'])?>/<?=h((string)$r['out_of'])?></strong> (<?=h((string)pct2($r['mark'],$r['out_of']))?>%)</td><td><?=h($r['comment']??'')?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="5">No results yet.</td></tr><?php endif;?></table></div>
<div class="card"><h2>Attendance</h2><table class="table"><tr><th>Date</th><th>Status</th></tr><?php foreach(array_slice(array_reverse($att),0,15) as $a):?><tr><td><?=h($a['date']??'')?></td><td><?=h($a['status']??'')?></td></tr><?php endforeach;?></table></div>
<div class="card"><h2>Account</h2><table class="table"><tr><th>Date</th><th>Description</th><th>Amount</th></tr><?php foreach(array_slice(array_reverse($lr),0,12) as $l):?><tr><td><?=h($l['date']??'')?></td><td><?=h($l['description']??'')?></td><td>R <?=number_format((float)$l['amount'],2)?></td></tr><?php endforeach;?></table></div>
<div class="card"><h2>Profile</h2><p><strong>Date of birth:</strong> <?=h($st['dob']??'—')?></p><p><strong>Email:</strong> <?=h($st['email']??'—')?></p><p><strong>Phone:</strong> <?=h($st['phone']??'—')?></p><p><strong>Parent:</strong> <?=h(nm($parents,(int)($st['parent_id']??0)))?></p></div>
